function starHub(edges) {
  const deg = new Array(edges.length + 2).fill(0);
  for (const [u, v] of edges) {
    deg[u]++;
    deg[v]++;
  }
  for (let i = 1; i < deg.length; i++) if (deg[i] === edges.length) return i;
  return -1;
}

